func msgClass(m ThreadMessage) string {
	switch {
	case m.IsNote:
		return "note"
	case m.IsStaff:
		return "staff"
	}
	return "player"
}

func ticketStatusClass(status string) string {
	switch status {
	case "open":
		return "badge-lamp"
	case "waiting":
		return "badge-info"
	}
	return "badge-soft"
}

// inboxHref keeps the other controls where they are when one changes.
func inboxHref(d InboxData, key, value string) string {
	status, topic, q := d.Status, d.Topic, d.Query
	priority, assignee, ticket := d.Priority, d.Assignee, ""
	if d.Thread != nil {
		ticket = d.Thread.ID
	}
	switch key {
	case "status":
		status = value
	case "topic":
		if topic == value {
			value = ""
		}
		topic = value
	case "priority":
		priority = value
	case "assignee":
		assignee = value
	case "t":
		ticket = value
	}
	out := "/admin/support?status=" + status + "&topic=" + topic + "&q=" + q +
		"&priority=" + priority + "&assignee=" + assignee
	if ticket != "" {
		out += "&t=" + ticket
	}
	return out
}

